async () => {
  const reported: unknown[] = []
  const calls: unknown[] = []
  const catalogRow = {
    id: "p1",
    name: "Shampoo X",
    brand: "Marke",
    category: "shampoo" as const,
    categoryLabel: "Shampoo",
